import * as T from './assets/three.js';
import {createSizedModel} from './product-scale.js';
const DEG=Math.PI/180;
function perimeter(w,d,r,n=24){const out=[];r=Math.min(r,w*.49,d*.49);const centers=[[w/2-r,d/2-r],[-w/2+r,d/2-r],[-w/2+r,-d/2+r],[w/2-r,-d/2+r]];for(let j=0;j<4;j++)for(let i=0;i<n;i++){const a=j*Math.PI/2+i/n*Math.PI/2;out.push([centers[j][0]+Math.cos(a)*r,centers[j][1]+Math.sin(a)*r])}return out}
function ringGeometry(rings,edge){const n=96,p=[],uv=[],idx=[];rings.forEach((r,k)=>edge(r).forEach(([x,z],j)=>{p.push(x,r.y,z);uv.push(j/n,k/Math.max(1,rings.length-1))}));for(let k=0;k<rings.length-1;k++)for(let j=0;j<n;j++){const a=k*n+j,b=k*n+(j+1)%n,c=a+n,d=b+n;idx.push(a,c,b,b,c,d)}const bottom=p.length/3;p.push(0,rings[0].y,0);uv.push(.5,.5);const top=p.length/3;p.push(0,rings.at(-1).y,0);uv.push(.5,.5);for(let j=0;j<n;j++){idx.push(bottom,j,(j+1)%n);const a=(rings.length-1)*n+j,b=(rings.length-1)*n+(j+1)%n;idx.push(top,b,a)}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();return g}
export function geometryFromRecipe(g){
 if(g.kind==='lathe')return new T.LatheGeometry(g.points.map(p=>new T.Vector2(p.radius,p.y)),160);
 if(g.kind==='loft')return ringGeometry(g.rings,r=>{const pts=[];for(let i=0;i<96;i++){const a=-i/96*Math.PI*2,s=Math.sin(a),c=Math.cos(a),power=2/g.power;pts.push([Math.sign(s)*Math.abs(s)**power*r.radiusX,Math.sign(c)*Math.abs(c)**power*r.radiusZ])}return pts});
 if(g.kind==='rounded_box'){const [w,h,d]=g.size,b=Math.min(g.bevel,Math.min(w,h,d)*.49);if(b<.001)return new T.BoxGeometry(w,h,d);const rings=[],steps=10;for(let i=0;i<=steps;i++){const a=i/steps*Math.PI/2;rings.push({y:-h/2+b*(1-Math.cos(a)),inset:b*(1-Math.sin(a))})}rings.push({y:h/2-b,inset:0});for(let i=1;i<=steps;i++){const a=i/steps*Math.PI/2;rings.push({y:h/2-b+b*Math.sin(a),inset:b*(1-Math.cos(a))})}return ringGeometry(rings,r=>perimeter(w-r.inset*2,d-r.inset*2,Math.max(.001,b-r.inset)))}
 if(g.kind==='cylinder')return new T.CylinderGeometry(g.radiusTop,g.radiusBottom,g.height,128);
 if(g.kind==='sphere'){const geometry=new T.SphereGeometry(g.radius,64,40);geometry.scale(...g.scale);return geometry}
 if(g.kind==='torus')return new T.TorusGeometry(g.radius,g.tube,14,160,g.arc);
 throw new Error('不支持的生成结构：'+g.kind);
}
export function materialPatternPixels(m,n=192){
 const rgb=hex=>[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)),base=rgb(m.color),secondary=rgb(m.secondaryColor),pixels=new Uint8ClampedArray(n*n*4);let seed=[...m.id].reduce((a,b)=>a+b.charCodeAt(0),71);const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967295-.5},columns=Array.from({length:n},()=>random()*.03);
 for(let y=0;y<n;y++)for(let x=0;x<n;x++){const k=(y*n+x)*4,t=y/Math.max(1,n-1),gain=m.pattern==='brushed'?1+columns[x]+random()*.006:1+random()*.05;for(let c=0;c<3;c++)pixels[k+c]=m.pattern==='vertical_gradient'?secondary[c]*(1-t)+base[c]*t:base[c]*gain;pixels[k+3]=255}return pixels;
}
function patternTexture(m){const c=document.createElement('canvas');c.width=c.height=192;const x=c.getContext('2d'),data=x.createImageData(192,192);data.data.set(materialPatternPixels(m));x.putImageData(data,0,0);const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;t.wrapS=t.wrapT=T.RepeatWrapping;if(m.pattern!=='vertical_gradient')t.repeat.set(3,2);return t}
export function migrateGeneratedMaterials(root){if(!Array.isArray(root.userData.generatedRecipe?.materials)||root.userData.generatedRenderRevision>=2)return false;const recipes=new Map(root.userData.generatedRecipe.materials.filter(m=>m.pattern!=='solid').map(m=>[m.name,m])),seen=new Set();let changed=false;root.traverse(node=>{for(const material of Array.isArray(node.material)?node.material:[node.material]){if(!material||seen.has(material))continue;seen.add(material);const recipe=recipes.get(material.name);if(!recipe)continue;material.map=patternTexture(recipe);if(['brushed','frosted'].includes(recipe.pattern)){material.bumpMap=material.map;material.bumpScale=recipe.pattern==='brushed'?.0008:.0015}material.needsUpdate=true;changed=true}});root.userData.generatedRenderRevision=2;return changed}

function materialFromRecipe(m){const material=new T.MeshPhysicalMaterial({name:m.name,color:m.pattern==='solid'?m.color:'#ffffff',roughness:m.roughness,metalness:m.metalness,clearcoat:m.clearcoat,clearcoatRoughness:m.clearcoatRoughness,transmission:m.transmission,opacity:m.opacity,transparent:m.opacity<1||m.transmission>0,ior:m.ior,thickness:.04,envMapIntensity:1});if(m.transmission>0)material.depthWrite=false;if(m.pattern!=='solid'){material.map=patternTexture(m);if(m.pattern==='frosted'||m.pattern==='brushed'){material.bumpMap=material.map;material.bumpScale=m.pattern==='brushed'?.0008:.0015}}return material}
function textTexture(label){const ratio=label.width/label.height,w=ratio>=1?2048:Math.max(64,Math.round(2048*ratio)),h=ratio>=1?Math.max(64,Math.round(2048/ratio)):2048;const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.textAlign='center';x.textBaseline='middle';x.fillStyle=label.color;const total=label.lines.reduce((n,l)=>n+l.fontSize*1.35,0);let y=(label.height-total)/2;for(const line of label.lines){x.font=line.weight+' '+(line.fontSize*h/label.height)+'px Arial, sans-serif';x.fillText(line.text,w/2,(y+line.fontSize*.65)*h/label.height,w*.96);y+=line.fontSize*1.35}return c}
function inkTexture(label,image){const [x,y,w,h]=label.sourceRect,c=document.createElement('canvas');c.width=Math.max(4,Math.min(1600,Math.round(image.width*w)));c.height=Math.max(4,Math.min(1600,Math.round(image.height*h)));const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,x*image.width,y*image.height,w*image.width,h*image.height,0,0,c.width,c.height);const blur=document.createElement('canvas');blur.width=c.width;blur.height=c.height;const bx=blur.getContext('2d');bx.filter='blur('+Math.max(3,c.width/50)+'px)';bx.drawImage(c,0,0);const src=ctx.getImageData(0,0,c.width,c.height),avg=bx.getImageData(0,0,c.width,c.height),out=ctx.createImageData(c.width,c.height),color=new T.Color(label.color);color.convertLinearToSRGB();const rgb=[color.r*255,color.g*255,color.b*255];for(let i=0;i<src.data.length;i+=4){const lum=(src.data[i]+src.data[i+1]+src.data[i+2])/3,mean=(avg.data[i]+avg.data[i+1]+avg.data[i+2])/3,diff=label.ink==='light'?lum-mean:mean-lum,alpha=T.MathUtils.clamp((diff-(label.ink==='light'?1.5:2))/(label.ink==='light'?10:14),0,1)*src.data[i+3];out.data.set([...rgb,alpha],i)}ctx.putImageData(out,0,0);return c}
function makeLabel(label,image){if(label.mode==='source_ink'&&!image)throw new Error('未上传图片，无法使用原图印刷；请重新研究并使用文字标签');const canvas=label.mode==='source_ink'?inkTexture(label,image):textTexture(label),map=new T.CanvasTexture(canvas);map.colorSpace=T.SRGBColorSpace;map.anisotropy=8;const material=new T.MeshBasicMaterial({map,transparent:true,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-1});let geometry;if(label.surface==='cylinder'){const arc=Math.min(Math.PI*1.8,label.width/label.radius);geometry=new T.CylinderGeometry(label.radius,label.radius,label.height,96,1,true,-arc/2,arc)}else geometry=new T.PlaneGeometry(label.width,label.height);const mesh=new T.Mesh(geometry,material);mesh.name=label.name;placeLabel(mesh,label);mesh.userData.noCastShadow=true;return mesh}
export function placeLabel(mesh,label){mesh.position.fromArray(label.position);mesh.rotation.set(...label.rotation.map(v=>v*DEG));if(label.surface==='cylinder'){mesh.position.x=0;mesh.rotation.y+=label.position[0]/label.radius}return mesh}
const safeUrl=url=>/^https?:\/\//.test(url||'')?url:'';
export function generatedProfile(recipe,id){return {id:'generated-'+id,name:recipe.identity.name,capacityValue:recipe.identity.capacityValue,capacityUnit:recipe.identity.capacityUnit||'',capacityMl:recipe.identity.capacityUnit==='ml'?recipe.identity.capacityValue:null,axis:'y',mm:recipe.dimensions.height,quality:({verified:'有同版尺寸依据',retailer_reference:'零售商尺寸参考 · 非实测',estimated:'尺寸估算 · 待实测'})[recipe.dimensions.quality],source:recipe.dimensions.basis,url:safeUrl(recipe.dimensions.sourceUrl),revision:1}}
export function generatedDossier(recipe,source,id){return {id:'generated-'+id,product:recipe.identity.name,spec:[recipe.identity.variant,recipe.identity.capacityValue==null?'':recipe.identity.capacityValue+' '+recipe.identity.capacityUnit].filter(Boolean).join(' · '),researchedAt:new Date().toISOString().slice(0,10),status:'本机 Codex 实际查资料后生成',identity:recipe.research.summary+' '+recipe.research.versionNotes,coverage:[{face:'同版参考',status:'已实际联网检索',source:recipe.research.sources.length+' 个来源'},{face:'包装尺寸',status:recipe.dimensions.quality==='estimated'?'估算，待实测':'有来源依据',source:recipe.dimensions.basis},...recipe.research.unknowns.map(text=>({face:'未查证',status:'仍缺可靠资料',source:text}))],sources:[...(source?[{id:'source',title:'本次载入的产品原图',kind:'用户原图',image:source,status:'采用',use:'外形比例、配色和正面字样的主基准'}]:[]),...recipe.research.sources.map((s,i)=>({id:'web-'+i,title:s.title,kind:'实际检索来源',url:safeUrl(s.url),status:'采用',use:s.evidence+' '+s.use}))],modeling:recipe.parts.map(p=>({part:p.name,basis:source?'原图与上述参考资料':'用户文字信息与上述参考资料',action:'独立 '+p.geometry.kind+' 几何与 '+p.materialId+' 材质'})),limitations:[recipe.dimensions.basis,...recipe.research.unknowns].join('；')}}
export async function createGeneratedProduct(recipe,source,id,calibration){if(recipe.status!=='ready'||!recipe.parts?.length||recipe.parts.length>80||!recipe.materials?.length||!recipe.research?.sources?.length)throw new Error('生成方案不完整，未加入场景。');const image=source?await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(new Error('无法读取生成模型的原图'));i.src=source}):null,materials=new Map(recipe.materials.map(m=>[m.id,materialFromRecipe(m)])),raw=new T.Group();for(const part of recipe.parts){const geometry=geometryFromRecipe(part.geometry),material=materials.get(part.materialId);if(!material)throw new Error('生成部件缺少材质');const mesh=new T.Mesh(geometry,material);mesh.name=part.name;mesh.position.fromArray(part.position);mesh.rotation.set(...part.rotation.map(v=>v*DEG));mesh.castShadow=material.transmission===0;mesh.receiveShadow=true;mesh.userData.noCastShadow=!mesh.castShadow;raw.add(mesh)}for(const label of recipe.labels)raw.add(makeLabel(label,image));raw.updateMatrixWorld(true);const bounds=new T.Box3().setFromObject(raw),size=bounds.getSize(new T.Vector3());if(![size.x,size.y,size.z].every(v=>Number.isFinite(v)&&v>.01))throw new Error('生成模型没有有效的三维尺寸');const dims=recipe.dimensions;for(const [actual,declared]of [[size.x,dims.width],[size.y,dims.height],[size.z,dims.depth]])if(actual/declared<.45||actual/declared>2.2)throw new Error('生成几何与声明尺寸相差过大，请重试建模。');const profile=generatedProfile(recipe,id),model=createSizedModel(raw,profile,calibration);model.userData.generatedRenderRevision=2;model.userData.generatedProfile=profile;model.userData.generatedRecipe=recipe;model.userData.generationId=id;return {model,profile,dossier:generatedDossier(recipe,source,id)}}
